 1→import { useState, useRef } from 'react';
 2→import { useTranslation } from '../LanguageContext';
 3→import { useAgent } from '../useAgent';
 4→import './ChatInput.css';
 5→
 6→export function ChatInput() {
 7→  const { t } = useTranslation();
 8→  const { sendMessage, isStreaming } = useAgent();
 9→  const [text, setText] = useState('');
10→  const textareaRef = useRef<HTMLTextAreaElement>(null);
11→
12→  const handleSend = () => {
13→    const trimmed = text.trim();
14→    if (!trimmed || isStreaming) return;
15→    sendMessage(trimmed);
16→    setText('');
17→    if (textareaRef.current) {
18→      textareaRef.current.style.height = 'auto';
19→    }
20→  };
21→
22→  const handleKeyDown = (e: React.KeyboardEvent) => {
23→    if (e.key === 'Enter' && !e.shiftKey) {
24→      e.preventDefault();
25→      handleSend();
26→    }
27→  };
28→
29→  const handleInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
30→    setText(e.target.value);
31→    const el = e.target;
32→    el.style.height = 'auto';
33→    el.style.height = Math.min(el.scrollHeight, 150) + 'px';
34→  };
35→
36→  return (
37→    <div className="chat-input">
38→      <textarea
39→        ref={textareaRef}
40→        className="chat-input__textarea"
41→        value={text}
42→        onChange={handleInput}
43→        onKeyDown={handleKeyDown}
44→        placeholder={isStreaming ? t('chatPlaceholderWaiting') : t('chatPlaceholder')}
45→        disabled={isStreaming}
46→        rows={1}
47→      />
48→      <button
49→        className="chat-input__send"
50→        onClick={handleSend}
51→        disabled={isStreaming || !text.trim()}
52→      >
53→        {t('send')}
54→      </button>
55→    </div>
56→  );
57→}
