 1→import { useEffect, useRef } from 'react';
 2→import { useTranslation } from '../LanguageContext';
 3→import { useAgent } from '../useAgent';
 4→import { ChatInput } from './ChatInput';
 5→import { MessageBubble } from './MessageBubble';
 6→import type { LangfuseStatus } from '../types';
 7→import './AgentPanel.css';
 8→
 9→interface AgentPanelProps {
10→  langfuseStatus: LangfuseStatus;
11→}
12→
13→export function AgentPanel({ langfuseStatus }: AgentPanelProps) {
14→  const { t } = useTranslation();
15→  const { messages, clearMessages } = useAgent();
16→  const bottomRef = useRef<HTMLDivElement>(null);
17→
18→  useEffect(() => {
19→    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
20→  }, [messages]);
21→
22→  return (
23→    <div className="agent-panel">
24→      <div className="agent-panel__header">
25→        <span className="agent-panel__title">{t('agentHeader')}</span>
26→        <div className="agent-panel__actions">
27→          <button
28→            className={`agent-panel__langfuse ${!langfuseStatus.enabled ? 'agent-panel__langfuse--disabled' : ''}`}
29→            disabled={!langfuseStatus.enabled}
30→            title={langfuseStatus.enabled ? t('openLangfuse') : t('langfuseNotConfigured')}
31→            onClick={() => {
32→              if (langfuseStatus.dashboardUrl) {
33→                window.open(langfuseStatus.dashboardUrl, '_blank', 'noopener,noreferrer');
34→              }
35→            }}
36→          >
37→            <img src="/langfuse-color.svg" alt="Langfuse" className="agent-panel__langfuse-icon" />
38→            {t('langfuseTraces')}
39→          </button>
40→          {messages.length > 0 && (
41→            <button className="agent-panel__clear" onClick={clearMessages}>
42→              {t('clear')}
43→            </button>
44→          )}
45→        </div>
46→      </div>
47→      <div className="agent-panel__messages">
48→        {messages.length === 0 && (
49→          <div className="agent-panel__empty">
50→            {t('agentEmptyState')}
51→          </div>
52→        )}
53→        {messages.map((msg, index) => (
54→          <MessageBubble key={msg.id} message={msg} messageIndex={index} />
55→        ))}
56→        <div ref={bottomRef} />
57→      </div>
58→      <ChatInput />
59→    </div>
60→  );
61→}
